def seed_data():
    """把静态数据集写入 CSV 文件"""
    df = pd.DataFrame(DATA)
    df["日期"] = pd.to_datetime(df["日期"])
    df = df.sort_values("日期").reset_index(drop=True)

    # 确保目录存在
    RAW_CSV_PATH.parent.mkdir(parents=True, exist_ok=True)

    # 写入 CSV（覆盖模式，因为是种子数据）
    df.to_csv(RAW_CSV_PATH, index=False, encoding="utf-8-sig")
    df.to_csv(CLEAN_CSV_PATH, index=False, encoding="utf-8-sig")
    print(f"✅ 成功写入 {len(df)} 条蓝莓价格数据到：{RAW_CSV_PATH}")
    print(f"   时间跨度：{df['日期'].min().date()} ~ {df['日期'].max().date()}")
    print(f"   覆盖产地：{', '.join(df['产地'].unique())}")


if __name__ == "__main__":
    seed_data()